//! CPython 3.12's character-type database, ported from the pinned
//! source tree's `Objects/unicodetype_db.h` by `tools/gen_unicode_data.py`
//! (regenerate with `python3.12 tools/gen_unicode_data.py`). The record
//! fields, masks, index split and extended-case encoding are upstream
//! `makeunicodedata.py` 3.3's; `types/unicode.rs` reads them through the
//! same accessors as CPython's `Objects/unicodectype.c`.

// Numbers keep the exact C spelling of the generated tables.
#![allow(non_upper_case_globals)]

/// Character-property bits, upstream's masks (`unicodectype.c`).
pub mod flags {
    pub const ALPHA: u32 = 0x1;
    pub const CASED: u32 = 0x2000;
    pub const CASE_IGNORABLE: u32 = 0x1000;
    pub const DECIMAL: u32 = 0x2;
    pub const DIGIT: u32 = 0x4;
    pub const EXTENDED_CASE: u32 = 0x4000;
    pub const LINEBREAK: u32 = 0x10;
    pub const LOWER: u32 = 0x8;
    pub const NUMERIC: u32 = 0x800;
    pub const PRINTABLE: u32 = 0x400;
    pub const SPACE: u32 = 0x20;
    pub const TITLE: u32 = 0x40;
    pub const UPPER: u32 = 0x80;
    pub const XID_CONTINUE: u32 = 0x200;
    pub const XID_START: u32 = 0x100;
}

/// One `_PyUnicode_TypeRecord`: case deltas or extended-case offsets,
/// decimal/digit values and the property bits.
#[derive(Clone, Copy)]
pub struct TypeRecord {
    pub upper: i32,
    pub lower: i32,
    pub title: i32,
    pub decimal: u8,
    pub digit: u8,
    pub flags: u32,
}

