pub const WHITESPACE: [u32; 29] = [
    0x0009, 0x000A, 0x000B, 0x000C, 0x000D, 0x001C, 0x001D, 0x001E, 0x001F, 0x0020, 0x0085, 0x00A0,
    0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200A,
    0x2028, 0x2029, 0x202F, 0x205F, 0x3000,
];
pub const LINEBREAK: [u32; 10] = [
    0x000A, 0x000B, 0x000C, 0x000D, 0x001C, 0x001D, 0x001E, 0x0085, 0x2028, 0x2029,
];

/// `gettyperecord`: the two-level index walk.
pub fn record(code: u32) -> &'static TypeRecord {
    if code >= 0x110000 {
        return &TYPE_RECORDS[0];
    }
    let index = INDEX1[(code >> SHIFT) as usize] as usize;
    let index = INDEX2[(index << SHIFT) + (code as usize & ((1 << SHIFT) - 1))];
    &TYPE_RECORDS[index as usize]
}
